# Surah At-Tahrim (chapter 66) — all ayat 1-12 (IDs 5230-5241)
SURAH = 66

ENTRIES = {
5230: (
"بسم اللہ الرّحْمٰن الرّحِیْم — اے نبی آپ کیوں اسے حرام کرتے ہیں جسے اللہ نے آپ کے لیے حلال کیا؟ آپ اپنی بیویوں کی رضامندی چاہتے ہیں — اور اللہ غفور رحیم ہے",
"""۱۔ محرّمات کی علت — یا أیها النبی لم تحرّمُ ما أحلّ الله لک; تبتغي مرضات أزواجک; و الله غفور رحیم۔
۲۔ ’’يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاتَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَّحِيمٌ‘‘ — اے نبی آپ کیوں اسے حرام کرتے ہیں جسے اللہ نے آپ کے لیے حلال کیا؟ آپ اپنی بیویوں کی رضامندی چاہتے ہیں — اور اللہ غفور رحیم ہے — یعنی اے نبی آپ کیوں اسے حرام کرتے ہیں جسے اللہ نے آپ کے لیے حلال کیا آپ اپنی بیویوں کی رضامندی چاہتے ہیں اور اللہ غفور رحیم ہے۔
۳۔ عملی سبق: اللہ کی حلال چیزوں کو حرام نہ ٹھہراؤ؛ اللہ سے ڈرو۔"""
),
5231: (
"اللہ نے تمہارے لیے اپنی قسموں کا کفارہ مقرر کر دیا ہے — اور اللہ تمہارا ولی ہے — اور وہ علیم حکیم ہے",
"""۱۔ قسموں کا کفارہ — قد فرض الله لکم تحلّۃ أیمانکم; و الله مولیکم; و هو العلیم الحکیم۔
۲۔ ’’قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّۃَ أَيْمَانِكُمْ وَاللَّهُ مَوْلَاكُمْ وَهُوَ الْعَلِيمُ الْحَكِيمُ‘‘ — اللہ نے تمہارے لیے اپنی قسموں کا کفارہ مقرر کر دیا ہے — اور اللہ تمہارا ولی ہے — اور وہ علیم حکیم ہے — یعنی اللہ نے تمہارے لیے اپنی قسموں کا کفارہ مقرر کر دیا ہے اور اللہ تمہارا ولی ہے اور وہ علیم حکیم ہے۔
۳۔ عملی سبق: قسموں کا کفارہ ادا کرو؛ اللہ سے ڈرو۔"""
),
5232: (
"اور جب نبی نے اپنی بعض بیویوں سے راز میں بات کی — پس جب اس نے اسے ظاہر کیا اور اللہ نے اسے نبی پر ظاہر کر دیا تو نبی نے کچھ بتایا اور کچھ سے چشم پوشی کی — پس جب اس نے اسے اسے بتایا تو اس نے کہا آپ کو یہ کس نے بتایا؟ فرمایا مجھے علیم خبیر نے بتایا",
"""۱۔ راز کی افشا — و إذ أسرّ النبی إلی بعض أزواجه حدیثًا فلما نبّأت به و أظهره الله علیه عرّف بعضه و أعرض عن بعض; فلما نبّأها به قالت من أنبأک هذا; قال نبّأنی العلیم الخبیر۔
۲۔ ’’وَإِذْ أَسَرَّ النَّبِيُّ إِلَىٰ بَعْضِ أَزْوَاجِهِ حَدِيثًا فَلَمَّا نَبَّأَتْ بِهِ وَأَظْهَرَهُ اللَّهُ عَلَيْهِ عَرَّفَ بَعْضَهُ وَأَعْرَضَ عَن بَعْضٍ فَلَمَّا نَبَّأَهَا بِهِ قَالَتْ مَنْ أَنبَأَكَ هَٰذَا قَالَ نَبَّأَنِيَ الْعَلِيمُ الْخَبِيرُ‘‘ — اور جب نبی نے اپنی بعض بیویوں سے راز میں بات کی — پس جب اس نے اسے ظاہر کیا اور اللہ نے اسے نبی پر ظاہر کر دیا تو نبی نے کچھ بتایا اور کچھ سے چشم پوشی کی — پس جب اس نے اسے اسے بتایا تو اس نے کہا آپ کو یہ کس نے بتایا؟ فرمایا مجھے علیم خبیر نے بتایا — یعنی اور جب نبی نے اپنی بعض بیویوں سے راز میں بات کی پس جب اس نے اسے ظاہر کیا اور اللہ نے اسے نبی پر ظاہر کر دیا تو نبی نے کچھ بتایا اور کچھ سے چشم پوشی کی پس جب اس نے اسے اسے بتایا تو اس نے کہا آپ کو یہ کس نے بتایا فرمایا مجھے علیم خبیر نے بتایا۔
۳۔ عملی سبق: راز کی حفاظت کرو؛ اللہ سے ڈرو۔"""
),
5233: (
"اگر تم دونوں اللہ کے حضور توبہ کرو تو تمہارے دل مائل ہو چکے ہیں — اور اگر تم نبی کے خلاف مدد کرو تو بے شک اللہ اس کا مددگار ہے اور جبریل اور صالح مؤمنین — اور اس کے بعد فرشتے مددگار ہیں",
"""۱۔ توبہ کا حکم — إن تتوبا إلی الله فقد صغت قلوبکما; و إن تظاهرا علیه فإن الله هو مولاه و جبریل و صالح المؤمنین; و الملائکۃ بعد ذلک ظهیر۔
۲۔ ’’إِن تَتُوبَا إِلَى اللَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا وَإِن تَظَاهَرَا عَلَيْهِ فَإِنَّ اللَّهَ هُوَ مَوْلَاهُ وَجِبْرِيلُ وَصَالِحُ الْمُؤْمِنِينَ وَالْمَلَائِكَۃُ بَعْدَ ذَٰلِكَ ظَهِيرٌ‘‘ — اگر تم دونوں اللہ کے حضور توبہ کرو تو تمہارے دل مائل ہو چکے ہیں — اور اگر تم نبی کے خلاف مدد کرو تو بے شک اللہ اس کا مددگار ہے اور جبریل اور صالح مؤمنین — اور اس کے بعد فرشتے مددگار ہیں — یعنی اگر تم دونوں اللہ کے حضور توبہ کرو تو تمہارے دل مائل ہو چکے ہیں اور اگر تم نبی کے خلاف مدد کرو تو بے شک اللہ اس کا مددگار ہے اور جبریل اور صالح مؤمنین اور اس کے بعد فرشتے مددگار ہیں۔
۳۔ عملی سبق: اللہ سے توبہ کرو؛ اللہ سے ڈرو۔"""
),
5234: (
"ممکن ہے کہ اگر وہ تمہیں طلاق دے دے تو اس کا رب اسے تمہاری جگہ سے بہتر بیویاں بدل دے — مسلمان مومن قانت تائب عابد سائح ثیبات اور کنواریاں",
"""۱۔ بہتر بیویاں — عسی ربه إن طلّقکنّ أن یُبدله أزواجًا خیرًا منکنّ مسلمات مؤمنات قانتات تائبات عابدات سائحات ثیبات و أبکارًا۔
۲۔ ’’عَسَىٰ رَبُّهُ إِن طَلَّقَكُنَّ أَن يُبْدِلَهُ أَزْوَاجًا خَيْرًا مِّنكُنَّ مُسْلِمَاتٍ مُّؤْمِنَاتٍ قَانِتَاتٍ تَائِبَاتٍ عَابِدَاتٍ سَائِحَاتٍ ثَيِّبَاتٍ وَأَبْكَارًا‘‘ — ممکن ہے کہ اگر وہ تمہیں طلاق دے دے تو اس کا رب اسے تمہاری جگہ سے بہتر بیویاں بدل دے — مسلمان مومن قانت تائب عابد سائح ثیبات اور کنواریاں — یعنی ممکن ہے کہ اگر وہ تمہیں طلاق دے دے تو اس کا رب اسے تمہاری جگہ سے بہتر بیویاں بدل دے مسلمان مومن قانت تائب عابد سائح ثیبات اور کنواریاں۔
۳۔ عملی سبق: اللہ کے حکم پر عمل کرو؛ اللہ سے ڈرو۔"""
),
5235: (
"اے ایمان والو اپنے آپ کو اور اپنے اہل و عیال کو ایسی آگ سے بچاؤ جس کا ایندھن انسان اور پتھر ہیں — اس پر ایسے فرشتے ہیں جو سخت اور طاقتور ہیں — وہ اللہ کی اس بات میں نافرمانی نہیں کرتے جو انہیں حکم دے اور وہ وہی کرتے ہیں جو انہیں حکم دیا جاتا ہے",
"""۱۔ اہل و عیال کی ذمہ داری — یا أیها الذین آمنوا قوا أنفسکم و أهلیکم نارًا وقودها الناس و الحجارۃ; علیها ملائکۃ غلاظ شداد لا یعصون الله ما أمرهم و یفعلون ما یؤمرون۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا وَقُودُهَا النَّاسُ وَالْحِجَارَۃُ عَلَيْهَا مَلَائِكَۃٌ غِلَاظٌ شِدَادٌ لَّا يَعْصُونَ اللَّهَ مَا أَمَرَهُمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ‘‘ — اے ایمان والو اپنے آپ کو اور اپنے اہل و عیال کو ایسی آگ سے بچاؤ جس کا ایندھن انسان اور پتھر ہیں — اس پر ایسے فرشتے ہیں جو سخت اور طاقتور ہیں — وہ اللہ کی اس بات میں نافرمانی نہیں کرتے جو انہیں حکم دے اور وہ وہی کرتے ہیں جو انہیں حکم دیا جاتا ہے — یعنی اے ایمان والو اپنے آپ کو اور اپنے اہل و عیال کو ایسی آگ سے بچاؤ جس کا ایندھن انسان اور پتھر ہیں اس پر ایسے فرشتے ہیں جو سخت اور طاقتور ہیں وہ اللہ کی اس بات میں نافرمانی نہیں کرتے جو انہیں حکم دے اور وہ وہی کرتے ہیں جو انہیں حکم دیا جاتا ہے۔
۳۔ عملی سبق: اپنے اہل و عیال کو جہنم سے بچاؤ؛ اللہ سے ڈرو۔"""
),
5236: (
"اے کافرو آج کوئی عذر نہ کریں — تمہیں وہی بدلہ دیا جائے گا جو تم کرتے تھے",
"""۱۔ عذر کی گنجائش نہیں — یا أیها الذین کفروا لا تعتذروا الیوم; إنما تُجزون ما کنتم تعملون۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ كَفَرُوا لَا تَعْتَذِرُوا الْيَوْمَ إِنَّمَا تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ‘‘ — اے کافرو آج کوئی عذر نہ کریں — تمہیں وہی بدلہ دیا جائے گا جو تم کرتے تھے — یعنی اے کافرو آج کوئی عذر نہ کریں تمہیں وہی بدلہ دیا جائے گا جو تم کرتے تھے۔
۳۔ عملی سبق: کفر چھوڑو؛ اللہ سے ڈرو۔"""
),
5237: (
"اے ایمان والو اللہ کے حضور حقیقی توبہ کرو — ممکن ہے تمہارا رب تمہارے گناہ معاف کر دے اور تمہیں ایسی جنتوں میں داخل کرے جن کے نیچے نہریں بہتی ہیں جس دن اللہ نبی کو اور اس کے ساتھ ایمان لانے والوں کو ذلیل نہیں کرے گا — ان کا نور ان کے آگے اور ان کے دائیں جانب دوڑ رہا ہوگا — وہ کہیں گے اے ہمارے رب ہمارا نور پورا کر دے اور ہمیں بخش دے — بے شک تو ہر چیز پر قادر ہے",
"""۱۔ توبہ نصوح — یا أیها الذین آمنوا توبوا إلی الله توبة نصوحًا عسی ربکم أن یکفّر عنکم سیئاتکم و یدخلکم جنات تجري من تحتها الأنهار; یوم لا یخزي الله النبي و الذین آمنوا معه; نورهم یسعی بین أیدیهم و بأیمانهم یقولون ربنا أتمم لنا نورنا و اغفر لنا; إنک علی کل شيء قدیر۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللَّهِ تَوْبَۃً نَّصُوحًا عَسَىٰ رَبُّكُمْ أَن يُكَفِّرَ عَنكُمْ سَيِّئَاتِكُمْ وَيُدْخِلَكُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ يَوْمَ لَا يُخْزِي اللَّهُ النَّبِيَّ وَالَّذِينَ آمَنُوا مَعَهُ نُورُهُمْ يَسْعَىٰ بَيْنَ أَيْدِيهِمْ وَبِأَيْمَانِهِمْ يَقُولُونَ رَبَّنَا أَتْمِمْ لَنَا نُورَنَا وَاغْفِرْ لَنَا إِنَّكَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ‘‘ — اے ایمان والو اللہ کے حضور حقیقی توبہ کرو — ممکن ہے تمہارا رب تمہارے گناہ معاف کر دے اور تمہیں ایسی جنتوں میں داخل کرے جن کے نیچے نہریں بہتی ہیں جس دن اللہ نبی کو اور اس کے ساتھ ایمان لانے والوں کو ذلیل نہیں کرے گا — ان کا نور ان کے آگے اور ان کے دائیں جانب دوڑ رہا ہوگا — وہ کہیں گے اے ہمارے رب ہمارا نور پورا کر دے اور ہمیں بخش دے — بے شک تو ہر چیز پر قادر ہے — یعنی اے ایمان والو اللہ کے حضور حقیقی توبہ کرو ممکن ہے تمہارا رب تمہارے گناہ معاف کر دے اور تمہیں ایسی جنتوں میں داخل کرے جن کے نیچے نہریں بہتی ہیں جس دن اللہ نبی کو اور اس کے ساتھ ایمان لانے والوں کو ذلیل نہیں کرے گا ان کا نور ان کے آگے اور ان کے دائیں جانب دوڑ رہا ہوگا وہ کہیں گے اے ہمارے رب ہمارا نور پورا کر دے اور ہمیں بخش دے بے شک تو ہر چیز پر قادر ہے۔
۳۔ عملی سبق: حقیقی توبہ کرو؛ اللہ سے ڈرو۔"""
),
5238: (
"اے نبی کافروں اور منافقوں سے جہاد کرو اور ان پر سختی کرو — اور ان کا ٹھکانا جہنم ہے — اور بہت بری جگہ ہے",
"""۱۔ جہاد — یا أیها النبی جاهد الکفار و المنافقین و اغلظ علیهم; و مأواهم جهنم; و بئس المصیر۔
۲۔ ’’يَا أَيُّهَا النَّبِيُّ جَاهِدِ الْكُفَّارَ وَالْمُنَافِقِينَ وَاغْلُظْ عَلَيْهِمْ وَمَأْوَاهُمْ جَهَنَّمُ وَبِئْسَ الْمَصِيرُ‘‘ — اے نبی کافروں اور منافقوں سے جہاد کرو اور ان پر سختی کرو — اور ان کا ٹھکانا جہنم ہے — اور بہت بری جگہ ہے — یعنی اے نبی کافروں اور منافقوں سے جہاد کرو اور ان پر سختی کرو اور ان کا ٹھکانا جہنم ہے اور بہت بری جگہ ہے۔
۳۔ عملی سبق: اللہ کی راہ میں جہاد کرو؛ اللہ سے ڈرو۔"""
),
5239: (
"اللہ نے کافروں کے لیے نوح کی بیوی اور لوط کی بیوی کی مثال بیان کی — وہ ہمارے دو نیک بندوں کے نکاح میں تھیں پھر انہوں نے ان کے ساتھ خیانت کی — پس اللہ نے ان کے بارے میں اللہ سے کچھ نہیں بے فائدہ کیا اور کہا تم دونوں باقی داخل ہونے والوں کے ساتھ آگ میں داخل ہو جاؤ",
"""۱۔ کافروں کی عورتوں کی مثال — ضرب الله مثلًا للذین کفروا امرأت نوح و امرأت لوط; کانتا تحت عبدین من عبادنا صالحین فخانتاهما فلم یُغنیا عنهما من الله شيئًا و قیل ادخلا النار مع الداخلین۔
۲۔ ’’ضَرَبَ اللَّهُ مَثَلًا لِّلَّذِينَ كَفَرُوا امْرَأَتَ نُوحٍ وَامْرَأَتَ لُوطٍ كَانَتَا تَحْتَ عَبْدَيْنِ مِنْ عِبَادِنَا صَالِحَيْنِ فَخَانَتَاهُمَا فَلَمْ يُغْنِيَا عَنْهُمَا مِنَ اللَّهِ شَيْئًا وَقِيلَ ادْخُلَا النَّارَ مَعَ الدَّاخِلِينَ‘‘ — اللہ نے کافروں کے لیے نوح کی بیوی اور لوط کی بیوی کی مثال بیان کی — وہ ہمارے دو نیک بندوں کے نکاح میں تھیں پھر انہوں نے ان کے ساتھ خیانت کی — پس اللہ نے ان کے بارے میں اللہ سے کچھ نہیں بے فائدہ کیا اور کہا تم دونوں باقی داخل ہونے والوں کے ساتھ آگ میں داخل ہو جاؤ — یعنی اللہ نے کافروں کے لیے نوح کی بیوی اور لوط کی بیوی کی مثال بیان کی وہ ہمارے دو نیک بندوں کے نکاح میں تھیں پھر انہوں نے ان کے ساتھ خیانت کی پس اللہ نے ان کے بارے میں اللہ سے کچھ نہیں بے فائدہ کیا اور کہا تم دونوں باقی داخل ہونے والوں کے ساتھ آگ میں داخل ہو جاؤ۔
۳۔ عملی سبق: خیانت نہ کرو؛ اللہ سے ڈرو۔"""
),
5240: (
"اور اللہ نے ایمان والوں کے لیے فرعون کی بیوی کی مثال بیان کی — جب اس نے کہا اے میرے رب میرے لیے اپنے پاس جنت میں ایک گھر بنا دے اور مجھے فرعون اور اس کے عمل سے بچا دے اور مجھے ظالم قوم سے بچا دے",
"""۱۔ آسِیہ کا ایمان — و ضرب الله مثلًا للذین آمنوا امرأت فرعون إذ قالت رب ابن لی عندک بیتا في الجنة و نجني من فرعون و عمله و نجني من القوم الظالمین۔
۲۔ ’’وَضَرَبَ اللَّهُ مَثَلًا لِّلَّذِينَ آمَنُوا امْرَأَتَ فِرْعَوْنَ إِذْ قَالَتْ رَبِّ ابْنِ لِي عِندَكَ بَيْتًا فِي الْجَنَّۃِ وَنَجِّنِي مِن فِرْعَوْنَ وَعَمَلِهِ وَنَجِّنِي مِنَ الْقَوْمِ الظَّالِمِينَ‘‘ — اور اللہ نے ایمان والوں کے لیے فرعون کی بیوی کی مثال بیان کی — جب اس نے کہا اے میرے رب میرے لیے اپنے پاس جنت میں ایک گھر بنا دے اور مجھے فرعون اور اس کے عمل سے بچا دے اور مجھے ظالم قوم سے بچا دے — یعنی اور اللہ نے ایمان والوں کے لیے فرعون کی بیوی کی مثال بیان کی جب اس نے کہا اے میرے رب میرے لیے اپنے پاس جنت میں ایک گھر بنا دے اور مجھے فرعون اور اس کے عمل سے بچا دے اور مجھے ظالم قوم سے بچا دے۔
۳۔ عملی سبق: اللہ سے لو؛ اللہ سے ڈرو۔"""
),
5241: (
"اور مریم بنت عمران جنہوں نے اپنی شرمگاہ کی حفاظت کی — پس ہم نے اس میں اپنی روح پھونکی اور اس نے اپنے رب کے کلمات اور اس کی کتابوں کی تصدیق کی — اور وہ اطاعت گزاروں میں سے تھی",
"""۱۔ مریم کی پاکدامنی — و مریم ابنت عمران التي أحصنت فرجها فنفخنا فیه من روحنا و صدّقت بکلمات ربها و کتبه و کانت من القانتین۔
۲۔ ’’وَمَرْيَمَ ابْنَتَ عِمْرَانَ الَّتِي أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهِ مِن رُّوحِنَا وَصَدَّقَتْ بِكَلِمَاتِ رَبِّهَا وَكُتُبِهِ وَكَانَتْ مِنَ الْقَانِتِينَ‘‘ — اور مریم بنت عمران جنہوں نے اپنی شرمگاہ کی حفاظت کی — پس ہم نے اس میں اپنی روح پھونکی اور اس نے اپنے رب کے کلمات اور اس کی کتابوں کی تصدیق کی — اور وہ اطاعت گزاروں میں سے تھی — یعنی اور مریم بنت عمران جنہوں نے اپنی شرمگاہ کی حفاظت کی پس ہم نے اس میں اپنی روح پھونکی اور اس نے اپنے رب کے کلمات اور اس کی کتابوں کی تصدیق کی اور وہ اطاعت گزاروں میں سے تھی۔
۳۔ عملی سبق: پاکدامنی اختیار کرو؛ اللہ سے ڈرو۔"""
),
}
